<!-- 自定义表单 -->
<template>
  <div class="tablx-box">
    <el-table
      v-loading="fetchLoading && data.length == 0"
      class="table"
      :data="data"
      ref="tableScroll"
      stripe
      border
      :max-height="maxHeight"
      :header-cell-style="{
        borderColor: '#003B7A',
        color: '#fff',
        height: '53px',
      }"
      :row-style="{
        color: '#fff',
      }"
      :cell-style="{
        padding: '3px',
        height: '50.8px',
        borderColor: '#00539F',
      }"
      row-class-name="tableRowClassName"
      :show-summary="showSummary"
      :summary-method="getSummaries"
      :element-loading-text="loadingText"
      @selection-change="handleSelectionChange"
      @mouseenter.native="autoScroll(true)"
      @mouseleave.native="autoScroll(false)"
    >
      <el-table-column
        v-if="selection"
        type="selection"
        align="center"
        width="55"
      />
      <el-table-column v-if="sort" label="Top" align="center" width="100">
        <template slot-scope="scope">
          {{ scope.$index + 1 }}
        </template>
      </el-table-column>

      <el-table-column
        v-for="(item, index) in tableTitle"
        :key="item.key ? item.key : index"
        align="center"
        :prop="item.prop"
        :label="item.label"
        :sortable="item.sortable"
        :width="item.width ? item.width : null"
      >
        <template slot-scope="scope">
          <template v-if="item.isBotton">
            <div style="display: flex; justify-content: space-between">
              <span style="padding-top: 7px"
                >{{ scope.row[scope.column.property] }}
              </span>
              <div class="inner-btn" @click="resetFn(scope.row)">重置</div>
            </div>
          </template>
          <template v-else>
            <span v-if="item.formatter"
              >{{
                item.formatter(
                  scope.row,
                  scope.column,
                  scope.row[scope.column.property],
                  scope.$index
                )
              }}
            </span>
            <span v-else
              >{{
                scope.row[scope.column.property]
                  ? scope.row[scope.column.property]
                  : "- -"
              }}
            </span>
          </template>
        </template>
      </el-table-column>
      <slot name="actionColumn" />
    </el-table>
  </div>
</template>

<script>
export default {
  name: "CustomTable",
  props: {
    data: {
      type: Array,
      default: () => [],
    },
    fetchLoading: {
      type: Boolean,
      default: false,
    },
    loadingText: {
      type: String,
      default: "加载中...",
    },
    tableColumn: {
      type: Array,
      default: () => [],
    },
    selection: {
      type: Boolean,
      default: false,
    },
    sort: {
      type: Boolean,
      default: false,
    },
    showSummary: {
      type: Boolean,
      default: false,
    },
    getSummaries: {
      type: Function,
    },
    maxHeight: {
      type: String,
      default: "410px",
    },
  },
  data() {
    return {
      scrolltimer: null,
      animate: false,
    };
  },
  computed: {
    tableTitle() {
      if (!this.data || this.data.length === 0) return [];
      const titles =
        this.tableColumn && this.tableColumn.length > 0
          ? this.tableColumn
          : (this.data &&
              this.data.length > 0 &&
              Object.keys(this.data[0]).map((item) => {
                return {
                  prop: item,
                  label: item,
                };
              })) ||
            [];
      return titles;
    },
  },
  mounted() {
    this.autoScroll();
  },
  beforeDestroy() {
    this.autoScroll(true);
  },
  methods: {
    handleSelectionChange(val) {
      if (this.selection) {
        this.$emit("selectionChange", val);
      }
    },
    toggleSelection(rows) {
      if (rows) {
        rows.forEach((row) => {
          this.$refs.table.toggleRowSelection(row);
        });
      } else {
        this.$refs.table.clearSelection();
      }
    },
    tableRowClassName({ row, rowIndex }) {
      if (rowIndex % 2 !== 0) {
        return "el-table__row--striped";
      }
    },
    resetFn(row) {
      this.$emit("resetFn", row);
    },

    autoScroll(stop) {
      const table = this.$refs.tableScroll;
      const divData = table.$refs.bodyWrapper;
      if (stop) {
        window.clearInterval(this.scrolltimer);
      } else {
        this.scrolltimer = window.setInterval(() => {
          divData.scrollTop += 1;
          if (
            divData.clientHeight + divData.scrollTop >=
            divData.scrollHeight
          ) {
            divData.scrollTop = 0;
          }
        }, 30);
      }
    },
  },
};
</script>
<style lang="scss" scoped>
.test-div {
  animation: fadeOut 500ms linear;
}

.inner-btn {
  width: 80px;
  height: 36px;
  cursor: pointer;
  text-align: center;
  line-height: 36px;
  color: #00d8f4;
  border-radius: 4px 4px 4px 4px;
  border: 1px solid #00d8f4;
  &:hover {
    background-color: #888585;
    color: #fff;
  }
}
::v-deep .el-table__header-wrapper {
  .has-gutter {
    color: #1d2129;
    th {
      background: #003b7a;
    }
    tr {
      background: #003b7a;
    }
  }
}

::v-deep .el-table__body {
  width: 100% !important;
}
::v-deep .el-table__footer {
  width: 100% !important;
}
::v-deep .el-table__header {
  width: 100% !important;
  border-bottom: 1px solid #031a3c;
}

::v-deep .el-table__empty-block {
  width: 100% !important;
}

::v-deep .cell.el-tooltip {
  width: 100% !important;
}

// 显示的颜色
::v-deep .el-table__body tr.el-table__row--striped td {
  background-color: #043272 !important;
}
::v-deep .el-table__row {
  background: #031a3c !important;
}

::v-deep .el-table__body tr:hover > td {
  background-color: #3d5e8d !important;
}

::v-deep .el-table--border,
.el-table--group {
  border: 1px solid #003b7a;
}

// 隐藏滚动条
::v-deep .el-table__body-wrapper {
  &::-webkit-scrollbar {
    // 整个滚动条
    width: 0 !important; // 纵向滚动条的宽度
    background: transparent;
    border: none;
  }

  &::-webkit-scrollbar-track {
    // 滚动条轨道
    border: none !important;
  }
  /* 滚动条轨道内部空白区域样式 */
  &::-webkit-scrollbar-track {
    background-color: transparent; /* 设置轨道背景色为浅灰色 */
  }
}
</style>
